from fractions import Fraction

count = int(input())
for i in range(count):
    parts = input().split()
    if parts[0] == "G":
        a, r = Fraction(parts[1]), Fraction(parts[2])
        start = int(parts[3])
        first = a * r**start
        if abs(r) >= 1:
            print(f"Problem {i + 1}: first term {first}, diverges")
        else:
            print(f"Problem {i + 1}: first term {first}, sum {first / (1 - r)}")
    else:
        A, m, B, k = [int(v) for v in parts[1:]]
        x = Fraction(A, 10**m) + Fraction(B, 10**(m + k)) / (1 - Fraction(1, 10**k))
        print(f"Problem {i + 1}: {x}")

from sympy import symbols, limit, oo, nan, sympify

n = symbols("n", integer=True, positive=True)
count = int(input())
for i in range(count):
    term = sympify(input(), locals={"n": n})  # the term a_n, in terms of n
    L = limit(term, n, oo)
    if L == 0:
        print(f"Problem {i + 1}: terms -> 0, the test says nothing")
    elif L == nan:
        print(f"Problem {i + 1}: no limit, diverges")
    else:
        print(f"Problem {i + 1}: terms -> {L}, diverges")
